package com.bank.cheque;

import java.math.BigDecimal;
import java.util.logging.*;

public class PalindromeDemo {
    private static final Logger log = Logger.getLogger(PalindromeDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // A true mirror code: 10, 20, 30, 20, 10
        CodeNode mirror = build(new String[]{"10", "20", "30", "20", "10"});
        // A non-mirror code: 10, 20, 30, 40, 50
        CodeNode notMirror = build(new String[]{"10", "20", "30", "40", "50"});

        PalindromeVerifier verifier = new PalindromeVerifier();

        log.info("Verifying first cheque security code (expect mirror=true)");
        boolean r1 = verifier.isPalindrome(mirror);
        log.info("Result 1 -> isMirror=" + r1);

        log.info("Verifying second cheque security code (expect mirror=false)");
        boolean r2 = verifier.isPalindrome(notMirror);
        log.info("Result 2 -> isMirror=" + r2);
    }

    private static CodeNode build(String[] values) {
        CodeNode dummy = new CodeNode(BigDecimal.ZERO);
        CodeNode tail = dummy;
        for (String v : values) {
            tail.next = new CodeNode(new BigDecimal(v));
            tail = tail.next;
        }
        return dummy.next;
    }
}

// ─── Would be in model/CodeNode.java ───
class CodeNode {
    BigDecimal value;
    CodeNode next;

    CodeNode(BigDecimal value) {
        this.value = value;
    }
}

// ─── Would be in service/PalindromeVerifier.java ───
class PalindromeVerifier {
    // O(n) time, O(1) space: find middle, reverse 2nd half, compare, restore.
    boolean isPalindrome(CodeNode head) {
        if (head == null || head.next == null) return true;

        // Step 1: find the middle with fast/slow pointers
        CodeNode slow = head, fast = head;
        while (fast.next != null && fast.next.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }

        // Step 2: reverse the second half (starts at slow.next)
        CodeNode secondHead = reverse(slow.next);

        // Step 3: compare first half against reversed second half
        boolean palindrome = true;
        CodeNode left = head, right = secondHead;
        while (right != null) {
            if (left.value.compareTo(right.value) != 0) {
                palindrome = false;
                break;
            }
            left = left.next;
            right = right.next;
        }

        // Step 4: restore the list by reversing the second half back
        slow.next = reverse(secondHead);
        return palindrome;
    }

    private CodeNode reverse(CodeNode node) {
        CodeNode prev = null, curr = node;
        while (curr != null) {
            CodeNode next = curr.next;
            curr.next = prev;
            prev = curr;
            curr = next;
        }
        return prev;
    }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override
    public String format(java.util.logging.LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(record.getMillis()),
            record.getLevel().getName(),
            record.getMessage());
    }
